        if (throwOnDispose)
        {
            throw new InvalidOperationException($"dispose failed: {Name}");
        }
    }
}

/// <summary>
/// try/finally loses the body's exception when the cleanup throws. This does
/// not: the body's failure stays primary, and every disposal still runs.
/// </summary>
public static class SafeScope
{
    public static void Run(Action body, params IDisposable[] resources)
    {
        ArgumentNullException.ThrowIfNull(body);
        ArgumentNullException.ThrowIfNull(resources);

        Exception? bodyFailure = null;
        try
        {
            body();
        }
        catch (Exception ex)
        {
            // Caught, not swallowed: it is re-surfaced below, after cleanup.
            bodyFailure = ex;
        }

        List<Exception> disposalFailures = new();

        // Reverse order: the last resource opened may depend on an earlier
        // one still being alive, exactly like nested using blocks.
        for (int i = resources.Length - 1; i >= 0; i--)
        {
            try
            {
                resources[i]?.Dispose();
            }
            catch (Exception ex)
            {
                disposalFailures.Add(ex);
            }
        }

        if (bodyFailure is null && disposalFailures.Count == 0)
        {
            return;
        }

        if (bodyFailure is not null && disposalFailures.Count == 0)
        {
            // Same instance, original stack: throw bodyFailure; would reset it.
            ExceptionDispatchInfo.Capture(bodyFailure).Throw();
        }

        List<Exception> all = new();
        if (bodyFailure is not null)
        {
            all.Add(bodyFailure);   // the primary failure comes first
        }

        all.AddRange(disposalFailures);
        throw new AggregateException("the scope failed", all);
    }
}

exercises.hints:
## Hint 1

The leak, stated precisely: a delegate holds a reference to its target object,
the bus holds the delegate, so the bus holds the subscriber. Your code has
dropped every reference to the subscriber and the collector can still see one,
through the invocation list. Returning a token makes removal something a
`using` can guarantee.

## Hint 2

Store the handlers in a list and have the token capture what it needs to
remove:

```csharp
private sealed class Token(EventBus bus, Action<string> handler) : IDisposable
{
    private bool removed;
    public void Dispose()
    {
        if (removed) return;
        removed = true;
        bus.handlers.Remove(handler);
    }
}
```

Removing by the *same delegate instance* is what makes this work — which is why
`bus.Fired -= (s, e) => ...` with a fresh lambda removes nothing.

## Hint 3

`Publish` iterates a snapshot (`handlers.ToArray()`) so a handler that
unsubscribes mid-publish does not invalidate the enumerator. Then each handler
gets its own `try`/`catch`, failures go into a list, and the aggregate is
thrown at the end. Decide whether a handler that unsubscribed *during* this
publish should still be called — the snapshot says yes, and that is a
defensible choice you should be able to state.

