// v3cc04_exception_design / ex3 - filters decide before unwinding.
// See lessons/v3cc04_exception_design/README.md, "Exercise 3".

namespace CSharpDojo.V3CC04_ExceptionDesign;

/// <summary>
/// The status code is a property, not a substring of the message: handlers
/// branch on data that cannot be reworded or localised out from under them.
/// </summary>
public sealed class TransientException : Exception
{
    public TransientException(string message, int statusCode)
        : base(message) => StatusCode = statusCode;

    public TransientException(string message, int statusCode, Exception inner)
        : base(message, inner) => StatusCode = statusCode;

    public int StatusCode { get; }
}

public static class Gateway
{
    public static string Call(Func<string> work, List<string> log)
    {
        ArgumentNullException.ThrowIfNull(work);
        ArgumentNullException.ThrowIfNull(log);

        try
        {
            return Invoke(work, log);
        }
        catch (TransientException ex) when (ex.StatusCode >= 500)
        {
            // A 404 declines this filter and propagates untouched, which is
            // the correct behaviour: retrying a not-found never helps.
            log.Add($"handled:{ex.StatusCode}");
            return "retry";
        }
    }

    /// <summary>
    /// Shows the two-pass model. Both catch clauses live in THIS frame, above
    /// Invoke's finally: the search pass evaluates the logging filter first,
    /// the unwind pass then runs the callee's finally, and only then does the
    /// chosen handler body run.
    /// </summary>
    public static string Observe(Func<string> work, List<string> log)
    {
        ArgumentNullException.ThrowIfNull(work);
        ArgumentNullException.ThrowIfNull(log);

        try
        {
            return Invoke(work, log);
        }
        catch (Exception) when (Note(log, "filter:evaluated"))
        {
            // Never reached: Note returns false, so this clause declines and
            // the search pass moves on to the next one. Legal despite the
            // more-specific catch below because this one has a filter.
            log.Add("outer:caught");
            return "outer";
        }
        catch (TransientException ex) when (ex.StatusCode >= 500)
        {
            log.Add($"handled:{ex.StatusCode}");
            return "retry";
        }
    }

    private static string Invoke(Func<string> work, List<string> log)
    {
        try
        {
            return work();
        }
        finally
        {
            // Runs during the unwind pass - after any filter further up.
            log.Add("callee:finally");
        }
    }

    /// <summary>
    /// A side-effecting filter: observes without handling. Cheap and total,
    /// because a filter that throws is swallowed and treated as false.
    /// </summary>
    private static bool Note(List<string> log, string entry)
    {
        log.Add(entry);
        return false;
    }
}

references.Ex4.cs:
// v3cc04_exception_design / ex4 - two faces, one core.
// See lessons/v3cc04_exception_design/README.md, "Exercise 4".

namespace CSharpDojo.V3CC04_ExceptionDesign;

/// <summary>
/// One parsing core with no opinion about how failure should be reported, and
/// two faces over it: Parse throws, TryParse does not. The Try face never
/// constructs an exception, which is the entire reason the pattern exists.
/// </summary>
public static class Quantity
{
    public static int CoreCalls { get; private set; }

    public static int ExceptionsCreated { get; private set; }

    public static void ResetCounters()
    {
        CoreCalls = 0;
        ExceptionsCreated = 0;
    }

    public static int Parse(string text)
    {
        ArgumentNullException.ThrowIfNull(text);

        if (TryCore(text, out int grams, out string? error))
        {
            return grams;
        }

        ExceptionsCreated++;
        throw new FormatException(error);
    }

    public static bool TryParse(string? text, out int grams)
    {
        // null is a legitimate "no" here, not a caller error: the Try face
        // exists precisely for input that may be anything.
        if (text is null)
        {
            grams = 0;
            return false;
        }

        return TryCore(text, out grams, out _);
    }

    public static int ParseOrDefault(string? text, int fallback) =>
        TryParse(text, out int grams) ? grams : fallback;

    /// <summary>
    /// Never throws, never allocates an exception, and allocates no substring
    /// on the failure path.
    /// </summary>
    private static bool TryCore(ReadOnlySpan<char> text, out int grams, out string? error)
    {
        CoreCalls++;
        grams = 0;

        if (text.IsEmpty)
        {
            error = "empty";
            return false;
        }

        int split = 0;
        while (split < text.Length && char.IsAsciiDigit(text[split]))
        {
            split++;
        }

        ReadOnlySpan<char> number = text[..split];
        ReadOnlySpan<char> unit = text[split..];

        if (number.IsEmpty)
        {
            error = $"'{text.ToString()}' is not a number";
            return false;
        }

        if (unit.IsEmpty)
        {
            error = "missing unit";
            return false;
        }

        if (!int.TryParse(number, out int value))
        {
            error = $"'{number.ToString()}' is not a number";
            return false;
        }

        if (value < 0)
        {
            error = "negative";
            return false;
        }

        int multiplier = unit switch
        {
            "kg" => 1000,
            "g" => 1,
            "lb" => 454,
            _ => 0,
        };

        if (multiplier == 0)
        {
            error = $"unknown unit '{unit.ToString()}'";
            return false;
        }

        grams = value * multiplier;
        error = null;
        return true;
    }
}

