// v3cc04_exception_design / ex5 - preserving the evidence.
// See lessons/v3cc04_exception_design/README.md, "Exercise 5".

using System.Runtime.CompilerServices;
using System.Runtime.ExceptionServices;

namespace CSharpDojo.V3CC04_ExceptionDesign;

public static class Deep
{
    /// <summary>Recurses so the stack trace has frames worth losing.</summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    public static void Fail(int depth)
    {
        if (depth > 0)
        {
            Fail(depth - 1);
            return;
        }

        throw new InvalidOperationException("bottom");
    }
}

public static class Rethrower
{
    /// <summary>The exception in flight continues; the frames below survive.</summary>
    public static void Preserve(int depth)
    {
        try
        {
            Deep.Fail(depth);
        }
        catch (InvalidOperationException)
        {
            throw;
        }
    }

    /// <summary>
    /// The same object, rethrown from here - which overwrites StackTrace and
    /// deletes every frame between the original throw and this line.
    /// </summary>
    public static void Reset(int depth)
    {
        try
        {
            Deep.Fail(depth);
        }
        catch (InvalidOperationException ex)
        {
            throw ex;
        }
    }

    /// <summary>
    /// Translation at a layer boundary: a new type that means something to the
    /// caller, with the original cause attached rather than discarded.
    /// </summary>
    public static void Wrap(int depth)
    {
        try
        {
            Deep.Fail(depth);
        }
        catch (InvalidOperationException ex)
        {
            throw new ImportFailedException("could not import", ex)
            {
                Line = depth,
                Field = "source",
            };
        }
    }

    /// <summary>
    /// `throw;` for when you are no longer inside the catch - the same
    /// machinery await uses to resurface a faulted task's exception.
    /// </summary>
    public static void Dispatch(int depth)
    {
        ExceptionDispatchInfo? captured = null;

        try
        {
            Deep.Fail(depth);
        }
        catch (InvalidOperationException ex)
        {
            captured = ExceptionDispatchInfo.Capture(ex);
        }

        captured?.Throw();
    }
}

public static class TraceReport
{
    public static (string Type, string? InnerType, bool MentionsFail) Describe(Action work)
    {
        ArgumentNullException.ThrowIfNull(work);

        try
        {
            work();
        }
        catch (Exception ex)
        {
            // The OUTER exception's own trace. A wrapper has a short one of
            // its own; the interesting frames are on InnerException.
            bool mentionsFail = ex.StackTrace?.Contains("Fail", StringComparison.Ordinal) == true;
            return (ex.GetType().Name, ex.InnerException?.GetType().Name, mentionsFail);
        }

        throw new InvalidOperationException("the action was expected to throw");
    }
}

references.Ex6.cs:
// v3cc04_exception_design / ex6 - what async does to a failure.
// See lessons/v3cc04_exception_design/README.md, "Exercise 6".

namespace CSharpDojo.V3CC04_ExceptionDesign;

public static class AsyncFailures
{
    /// <summary>
    /// Async all the way, so even the validation at the top faults the
    /// returned task instead of throwing at the call site.
    /// </summary>
    public static async Task<int> ValidateThenWork(string? input)
    {
        ArgumentNullException.ThrowIfNull(input);

        await Task.Yield();
        return input.Length;
    }

    /// <summary>
    /// The documented convention for argument validation: a non-async wrapper
    /// throws synchronously, and a local function carries the awaits.
    /// </summary>
    public static Task<int> ValidateEagerly(string? input)
    {
        ArgumentNullException.ThrowIfNull(input);

        return Core(input);

        static async Task<int> Core(string text)
        {
            await Task.Yield();
            return text.Length;
        }
    }

    /// <summary>
    /// await unwraps to the first exception, however many tasks failed.
    /// </summary>
    public static async Task<string> FirstFailureOf(params Func<Task>[] work)
    {
        ArgumentNullException.ThrowIfNull(work);

        Task[] tasks = work.Select(w => w()).ToArray();
        try
        {
            await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            return ex.GetType().Name;
        }

        return "none";
    }

    /// <summary>
    /// Every failure, in task order. Walking the tasks themselves is more
    /// reliable than reading the aggregate, which makes no ordering promise
    /// and may hold nested aggregates.
    /// </summary>
    public static async Task<IReadOnlyList<string>> AllFailuresOf(params Func<Task>[] work)
    {
        ArgumentNullException.ThrowIfNull(work);

        Task[] tasks = work.Select(w => w()).ToArray();

        try
        {
            await Task.WhenAll(tasks);
        }
        catch
        {
            // Swallowed deliberately: the failures are collected below, from
            // the tasks, so nothing is lost.
        }

        List<string> failures = new();
        foreach (Task task in tasks)
        {
            if (task.Exception is { } aggregate)
            {
                foreach (Exception inner in aggregate.Flatten().InnerExceptions)
                {
                    failures.Add(inner.GetType().Name);
                }
            }
        }

        return failures;
    }
}

references.Ex7.cs:
// v3cc04_exception_design / ex7 - cancellation is not failure.
// See lessons/v3cc04_exception_design/README.md, "Exercise 7".

namespace CSharpDojo.V3CC04_ExceptionDesign;

public static class Caller
{
    /// <summary>
    /// Runs work under a timeout linked to the caller's own token, and
    /// classifies the outcome. Both causes throw OperationCanceledException;
    /// only the tokens can say which one happened.
    /// </summary>
    public static async Task<(string Outcome, string? Value, string? Error)> Run(
        Func<CancellationToken, Task<string>> work,
        TimeSpan timeout,
        CancellationToken callerToken)
    {
        ArgumentNullException.ThrowIfNull(work);

        // Both sources hold real resources - a timer queue entry and a
        // registration on each linked token - so both are disposed.
        using CancellationTokenSource timeoutSource = new(timeout);
        using CancellationTokenSource linked =
            CancellationTokenSource.CreateLinkedTokenSource(callerToken, timeoutSource.Token);

        try
        {
            string value = await work(linked.Token).ConfigureAwait(false);
            return ("completed", value, null);
        }
        catch (OperationCanceledException) when (callerToken.IsCancellationRequested)
        {
            // Checked first: if both fired at once, the caller's intent is the
            // more useful explanation. Not an error, so no message.
            return ("cancelled", null, null);
        }
        catch (OperationCanceledException)
        {
            // "A task was canceled." tells nobody anything; the duration does.
            return ("timedout", null, $"timed out after {timeout.TotalMilliseconds:0}ms");
        }
        catch (Exception ex)
        {
            return ("failed", null, ex.Message);
        }
    }

    /// <summary>
    /// A cancelled request is a user closing a tab. Logging it as an error
    /// makes the error rate a measure of impatience.
    /// </summary>
    public static bool ShouldLogAsError(string outcome) =>
        outcome is "failed" or "timedout";
}

